```c
/*
 * wave_core.c -- OpenWave ADC sampling core implementation.
 *
 * M2 milestone: opens the ADC character device, reads batches of samples
 * with read(), and stores them in a 512-sample ring buffer for the DSP
 * layer added in M4.
 */

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#include <nuttx/analog/adc.h>
#include <nuttx/analog/ioctl.h>

#include "wave_core.h"

/* Push one sample into the ring buffer, discarding the oldest when full. */
static void wave_core_push(FAR struct wave_core_s *core, uint8_t ch,
                           int32_t raw)
{
  uint16_t tail;

  tail = (core->head + core->count) & (WAVE_ADC_BUFSIZE - 1);
  core->ch[tail] = ch;
  core->raw[tail] = raw;

  if (core->count < WAVE_ADC_BUFSIZE)
    {
      core->count++;
    }
  else
    {
      core->head = (core->head + 1) & (WAVE_ADC_BUFSIZE - 1);
    }
}

int wave_core_init(struct wave_core_s *core, const char *devpath)
{
  int nchannels = 0;

  if (core == NULL)
    {
      return -EINVAL;
    }

  memset(core, 0, sizeof(*core));
  core->fd = -1;

  if (devpath == NULL)
    {
      devpath = WAVE_ADC_DEVPATH;
    }

  core->fd = open(devpath, O_RDONLY);
  if (core->fd < 0)
    {
      return -errno;
    }

  core->opened = true;

  /* Channel count is informational only; not all drivers implement it. */
  if (ioctl(core->fd, ANIOC_GET_NCHANNELS, (unsigned long)(uintptr_t)&nchannels) == 0)
    {
      core->nchannels = nchannels;
    }

  return 0;
}

void wave_core_deinit(struct wave_core_s *core)
{
  if (core != NULL && core->opened)
    {
      close(core->fd);
      core->fd = -1;
      core->opened = false;
    }
}

int wave_core_read(struct wave_core_s *core, struct wave_sample_s *samples,
                   int max_samples)
{
  struct adc_msg_s msgbuf[WAVE_ADC_BATCH];
  size_t maxread;
  ssize_t nbytes;
  int nsamples;
  int i;

  if (core == NULL || !core->opened)
    {
      return -EINVAL;
    }

  if (max_samples <= 0)
    {
      max_samples = WAVE_ADC_BATCH;
    }

  if (max_samples > WAVE_ADC_BATCH)
    {
      max_samples = WAVE_ADC_BATCH;
    }

  maxread = (size_t)max_samples * sizeof(struct adc_msg_s);
  nbytes = read(core->fd, msgbuf, maxread);
  if (nbytes < 0)
    {
      if (errno == EINTR)
        {
          return 0;
        }

      return -errno;
    }

  nsamples = nbytes / sizeof(struct adc_msg_s);
  for (i = 0; i < nsamples; i++)
    {
      wave_core_push(core, msgbuf[i].am_channel, msgbuf[i].am_data);
      if (samples != NULL)
        {
          samples[i].ch = msgbuf[i].am_channel;
          samples[i].raw = msgbuf[i].am_data;
        }
    }

  return nsamples;
}

uint32_t wave_core_to_mv(int32_t raw)
{
  if (raw < 0)
    {
      raw = 0;
    }

  return (uint32_t)(((uint64_t)raw * WAVE_ADC_VREF_MV) / WAVE_ADC_FULLSCALE);
}
```

