+    {
+      if (errno == EINTR)
+        {
+          return 0;
+        }
+
+      return -errno;
+    }
+
+  nsamples = nbytes / sizeof(struct adc_msg_s);
+  for (i = 0; i < nsamples; i++)
+    {
+      wave_core_push(core, msgbuf[i].am_channel, msgbuf[i].am_data);
+
+      if (samples != NULL)
+        {
+          samples[i].ch = msgbuf[i].am_channel;
+          samples[i].raw = msgbuf[i].am_data;
+        }
+    }
