#define __APPS_OPENWAVE_WAVE_GEN_H

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>

/* Default PWM device path (may be overridden on the command line). */
#define WAVE_PWM_DEVPATH   "/dev/pwm0"

struct wave_gen_s
{
  int  fd;        /* open file descriptor for the PWM device */
  bool opened;    /* true once the device is open */
  bool running;   /* true while the pulse train is running */
  uint32_t freq;  /* current frequency in Hz */
  uint32_t duty;  /* current duty cycle in percent */
};

/* Open the PWM device.  devpath may be NULL to use WAVE_PWM_DEVPATH.
 * Returns 0 on success or a negative errno value.
 */
int wave_gen_init(struct wave_gen_s *gen, const char *devpath);

/* Close the PWM device (stops the output first if it is running). */
void wave_gen_deinit(struct wave_gen_s *gen);

/* Start a pulse train.  freq_hz must be > 0; duty_pct is clamped to
 * [0, 100].  Returns 0 on success or a negative errno value.
 */
int wave_gen_start(struct wave_gen_s *gen, uint32_t freq_hz,
                   uint32_t duty_pct);

/* Stop the pulse train.  Returns 0 on success or a negative errno. */
int wave_gen_stop(struct wave_gen_s *gen);

#endif /* __APPS_OPENWAVE_WAVE_GEN_H */
OPENWAVE_EOF

cat > wave_gen.c <<'OPENWAVE_EOF'
/*
 * wave_gen.c -- OpenWave test-signal generator implementation.
 *
 * Uses the standard NuttX PWM character driver interface:
 *   open() -> ioctl(PWMIOC_SETCHARACTERISTICS) -> ioctl(PWMIOC_START)
 *   -> ioctl(PWMIOC_STOP) -> close()
 */

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>

#include <fixedmath.h>
#include <nuttx/timers/pwm.h>

#include "wave_gen.h"

int wave_gen_init(struct wave_gen_s *gen, const char *devpath)
{
  if (gen == NULL)
    {
      return -EINVAL;
    }

  memset(gen, 0, sizeof(*gen));
  gen->fd = -1;

  if (devpath == NULL)
    {
      devpath = WAVE_PWM_DEVPATH;
    }

  gen->fd = open(devpath, O_RDONLY);
  if (gen->fd < 0)
    {
      return -errno;
    }

  gen->opened = true;
  return 0;
}

void wave_gen_deinit(struct wave_gen_s *gen)
{
  if (gen != NULL && gen->opened)
    {
      if (gen->running)
        {
          wave_gen_stop(gen);
        }

      close(gen->fd);
      gen->fd = -1;
      gen->opened = false;
    }
}

int wave_gen_start(struct wave_gen_s *gen, uint32_t freq_hz,
                   uint32_t duty_pct)
{
  struct pwm_info_s info;
  int ret;

  if (gen == NULL || !gen->opened || freq_hz == 0)
    {
      return -EINVAL;
    }

  if (duty_pct > 100)
    {
      duty_pct = 100;
    }

  memset(&info, 0, sizeof(info));
  info.frequency = freq_hz;

  /* Convert a percentage to ub16_t duty as in apps/examples/pwm. */
  info.duty = duty_pct != 0 ? b16divi(uitoub16(duty_pct) - 1, 100) : 0;

  ret = ioctl(gen->fd, PWMIOC_SETCHARACTERISTICS,
              (unsigned long)(uintptr_t)&info);
  if (ret < 0)
    {
      return -errno;
    }

  ret = ioctl(gen->fd, PWMIOC_START, 0);
  if (ret < 0)
    {
      return -errno;
    }

  gen->freq = freq_hz;
  gen->duty = duty_pct;
  gen->running = true;
  return 0;
}

int wave_gen_stop(struct wave_gen_s *gen)
{
  int ret;

  if (gen == NULL || !gen->opened)
    {
      return -EINVAL;
    }

  ret = ioctl(gen->fd, PWMIOC_STOP, 0);
  if (ret < 0)
    {
      return -errno;
    }

  gen->running = false;
  return 0;
}
