double wave_dsp_zero_cross_freq(const int32_t *data, int n, double sample_rate)
{
  double mean = wave_dsp_mean(data, n);
  double crossings = 0.0;
  int prev_pos = 0;
  int i;
  if (n < 2 || sample_rate <= 0.0) return 0.0;

  /* hysteresis in raw units (~1.5% of full scale) to reject noise */
  const double hyst = 1000.0;

  for (i = 0; i < n; i++)
    {
      double v = data[i] - mean;
      int pos;
      if (v > hyst) pos = 1;
      else if (v < -hyst) pos = -1;
      else continue;  /* dead zone */

      if (prev_pos != 0 && pos != prev_pos)
        {
          crossings += 1.0;
        }
      prev_pos = pos;
    }

  /* each full cycle has 2 zero crossings */
  return crossings * sample_rate / (2.0 * (n - 1));
}
```

