FFT — radix-2 iterative, in-place, double precision:

```c
void wave_dsp_fft(double *re, double *im, int n)
{
  int levels, step, k, m, i;
  double temp_re, temp_im;
  double angle, w_re, w_im, wr, wi;

  /* bit reversal */
  for (i = 1, k = 0; i < n; i++)
    {
      int bit = n >> 1;
      for (; k & bit; bit >>= 1) k ^= bit;
      k ^= bit;
      if (i < k)
        {
          temp_re = re[i]; re[i] = re[k]; re[k] = temp_re;
          temp_im = im[i]; im[i] = im[k]; im[k] = temp_im;
        }
    }

  /* butterflies */
  for (step = 2; step <= n; step <<= 1)
    {
      int half = step >> 1;
      angle = -2.0 * M_PI / step;
      w_re = cos(angle); w_im = sin(angle);
      wr = 1.0; wi = 0.0;
      for (m = 0; m < half; m++)
        {
          for (k = m; k < n; k += step)
            {
              int j = k + half;
              temp_re = wr * re[j] - wi * im[j];
              temp_im = wr * im[j] + wi * re[j];
              re[j] = re[k] - temp_re;
              im[j] = im[k] - temp_im;
              re[k] += temp_re;
              im[k] += temp_im;
            }
          temp_re = wr * w_re - wi * w_im;
          temp_im = wr * w_im + wi * w_re;
          wr = temp_re; wi = temp_im;
        }
    }
}
```

