/*
 * test_dsp.c -- host-side sanity check for wave_dsp.
 *
 * NOT part of the OpenWave target build.  Compile on the host with:
 *   gcc -O2 -Wall -Wextra -I ../src test_dsp.c ../src/wave_dsp.c -lm -o test_dsp
 *
 * Expected results (synthetic signals, 16-bit ADC scale 0..65535):
 *   DC  : mean=rms=32767, vpp=0, f=0, FFT none
 *   SQ  : mean~32767, rms~46340 (65535/sqrt(2)), vpp=65535, f~1000 Hz
 *   SIN : mean~32767, rms~38951, vpp~59578, f~1000 Hz
 */

#include <math.h>
#include <stdint.h>
#include <stdio.h>

#include "wave_dsp.h"

#define RATE 50000.0
#define N    256

static void gen_square(int32_t *buf, int n, double vlow, double vhigh,
                       double duty, double freq, double rate)
{
  int i;

  for (i = 0; i < n; i++)
    {
      double cycle = fmod((double)i / rate * freq, 1.0);
      buf[i] = cycle < duty ? (int32_t)vhigh : (int32_t)vlow;
    }
}

static void gen_sine(int32_t *buf, int n, double offset, double amp,
                     double freq, double rate)
{
  int i;

  for (i = 0; i < n; i++)
    {
      buf[i] = (int32_t)(offset + amp * sin(2.0 * M_PI * freq * i / rate));
    }
}

static void show(const char *name, const int32_t *buf, int n, double rate)
{
  struct wave_stats_s st;
  double re[N];
  double im[N];
  double ff;
  int ret;

  wave_dsp_analyze(buf, n, rate, &st);
  printf("%-5s mean=%10.1f rms=%10.1f vpp=%10.1f f=%.1f",
         name, st.mean_raw, st.rms_raw, st.vpp_raw, st.freq_zc);

  ret = wave_dsp_fft_freq(buf, n, rate, re, im, &ff, NULL);
  if (ret == 0)
    {
      printf(" fft=%.1f", ff);
    }
  else
    {
      printf(" fft=n/a");
    }

  printf("\n");
}

int main(void)
{
  int32_t buf[N];

  /* DC at mid-scale (1.65 V). */
  {
    int i;

    for (i = 0; i < N; i++)
      {
        buf[i] = 32767;
      }
  }
  show("DC", buf, N, RATE);

  /* Square wave 0..3.3 V, 50 % duty, 1 kHz. */
  gen_square(buf, N, 0.0, 65535.0, 0.5, 1000.0, RATE);
  show("SQ", buf, N, RATE);

  /* Sine, 1.65 V offset, 1.5 V amplitude, 1 kHz. */
  gen_sine(buf, N, 32767.0, 29789.0, 1000.0, RATE);
  show("SIN", buf, N, RATE);

  return 0;
}

