```bash
cat > openwave_main.c <<'OPENWAVE_EOF'
/*
 * openwave_main.c -- OpenWave application entry point.
 *
 * M5 milestone: draws the waveform and measured parameters on the
 * SSD1306 OLED (/dev/lcd0) when available.  Serial output remains.
 */

#include <nuttx/config.h>

#include <inttypes.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "wave_core.h"
#include "wave_gen.h"
#include "wave_ui.h"

#define OPENWAVE_NAME    "OpenWave"
#define OPENWAVE_VERSION "0.5.0"

#ifndef CONFIG_OPENWAVE_ADC_DEVPATH
#  define CONFIG_OPENWAVE_ADC_DEVPATH WAVE_ADC_DEVPATH
#endif

#ifndef CONFIG_OPENWAVE_ADC_NSAMPLES
#  define CONFIG_OPENWAVE_ADC_NSAMPLES 64
#endif

#ifndef CONFIG_OPENWAVE_PWM_DEVPATH
#  define CONFIG_OPENWAVE_PWM_DEVPATH WAVE_PWM_DEVPATH
#endif

#ifndef CONFIG_OPENWAVE_PWM_DEFAULT_FREQ
#  define CONFIG_OPENWAVE_PWM_DEFAULT_FREQ 0
#endif

#ifndef CONFIG_OPENWAVE_PWM_DEFAULT_DUTY
#  define CONFIG_OPENWAVE_PWM_DEFAULT_DUTY 50
#endif

#ifndef CONFIG_OPENWAVE_ANALYZE_WINDOW
#  define CONFIG_OPENWAVE_ANALYZE_WINDOW 256
#endif

#ifndef CONFIG_OPENWAVE_ANALYZE_CHANNEL
#  define CONFIG_OPENWAVE_ANALYZE_CHANNEL 5
#endif

/* FFT scratch buffers are static so they do not eat task stack space. */
static double s_fft_re[WAVE_DSP_MAX_FFT];
static double s_fft_im[WAVE_DSP_MAX_FFT];

static void show_usage(const char *progname)
{
  printf("Usage: %s [OPTIONS]\n", progname);
  printf("  -d <device>  ADC device path (default: %s)\n",
         CONFIG_OPENWAVE_ADC_DEVPATH);
  printf("  -n <samples> Number of samples to print; 0 = run forever"
         " (default: %d)\n", CONFIG_OPENWAVE_ADC_NSAMPLES);
  printf("  -t           Issue ANIOC_TRIGGER before every read\n");
  printf("  -p <device>  PWM device path (default: %s)\n",
         CONFIG_OPENWAVE_PWM_DEVPATH);
  printf("  -f <freq>    Start PWM test signal at freq Hz"
         " (default: %d = off)\n", CONFIG_OPENWAVE_PWM_DEFAULT_FREQ);
  printf("  -D <duty>    PWM duty in percent, 0-100 (default: %d)\n",
         CONFIG_OPENWAVE_PWM_DEFAULT_DUTY);
  printf("  -w <window>  Samples per stats window; 0 = raw sample mode"
         " (default: %d)\n", CONFIG_OPENWAVE_ANALYZE_WINDOW);
  printf("  -c <channel> ADC channel to analyze (default: %d)\n",
         CONFIG_OPENWAVE_ANALYZE_CHANNEL);
  printf("  -h           Show this help and exit\n");
}

int main(int argc, char *argv[])
{
  const char *adc_devpath = CONFIG_OPENWAVE_ADC_DEVPATH;
  const char *pwm_devpath = CONFIG_OPENWAVE_PWM_DEVPATH;
  long remaining = CONFIG_OPENWAVE_ADC_NSAMPLES;
  long pwm_freq = CONFIG_OPENWAVE_PWM_DEFAULT_FREQ;
  long pwm_duty = CONFIG_OPENWAVE_PWM_DEFAULT_DUTY;
  long window = CONFIG_OPENWAVE_ANALYZE_WINDOW;
  long channel = CONFIG_OPENWAVE_ANALYZE_CHANNEL;
  bool infinite;
  bool swtrig = false;
  struct wave_core_s core;
  struct wave_gen_s gen;
  struct wave_sample_s samples[WAVE_ADC_BATCH];
  struct wave_ui_s ui;
  int32_t win[WAVE_DSP_MAX_FFT];
  struct wave_stats_s stats;
  double rate;
  double ffreq;
  bool pwm_on = false;
  bool ui_on = false;
  char line[32];
  int argi;
  int ret;
  int n;
  int i;

  for (argi = 1; argi < argc; argi++)
    {
      if (strcmp(argv[argi], "-d") == 0 && argi + 1 < argc)
        {
          adc_devpath = argv[++argi];
        }
      else if (strcmp(argv[argi], "-n") == 0 && argi + 1 < argc)
        {
          remaining = strtol(argv[++argi], NULL, 10);
          if (remaining < 0)
            {
              remaining = 0;
            }
        }
      else if (strcmp(argv[argi], "-t") == 0)
        {
          swtrig = true;
        }
      else if (strcmp(argv[argi], "-p") == 0 && argi + 1 < argc)
        {
          pwm_devpath = argv[++argi];
        }
      else if (strcmp(argv[argi], "-f") == 0 && argi + 1 < argc)
        {
          pwm_freq = strtol(argv[++argi], NULL, 10);
          if (pwm_freq < 0)
            {
              pwm_freq = 0;
            }
        }
      else if (strcmp(argv[argi], "-D") == 0 && argi + 1 < argc)
        {
          pwm_duty = strtol(argv[++argi], NULL, 10);
          if (pwm_duty < 0)
            {
              pwm_duty = 0;
            }
          else if (pwm_duty > 100)
            {
              pwm_duty = 100;
            }
        }
      else if (strcmp(argv[argi], "-w") == 0 && argi + 1 < argc)
        {
          window = strtol(argv[++argi], NULL, 10);
          if (window < 0)
            {
              window = 0;
            }
          else if (window > WAVE_DSP_MAX_FFT)
            {
              window = WAVE_DSP_MAX_FFT;
            }
        }
      else if (strcmp(argv[argi], "-c") == 0 && argi + 1 < argc)
        {
          channel = strtol(argv[++argi], NULL, 10);
          if (channel < 0 || channel > 255)
            {
              channel = CONFIG_OPENWAVE_ANALYZE_CHANNEL;
            }
        }
      else if (strcmp(argv[argi], "-h") == 0)
        {
          show_usage(argv[0]);
          return 0;
        }
      else
        {
          printf("Unknown option: %s\n", argv[argi]);
          show_usage(argv[0]);
          return 1;
        }
    }

  printf("%s v%s\n", OPENWAVE_NAME, OPENWAVE_VERSION);
  printf("M5: acquisition + DSP + OLED + PWM self-loop -- adc %s, %ld %s (%s)\n",
         adc_devpath, remaining,
         window > 0 ? "window(s)" : "samples",
         remaining == 0 ? "unlimited" : "then exit");

  /* Optional test-signal generator (PWM -> jumper -> ADC). */
  if (pwm_freq > 0)
    {
      ret = wave_gen_init(&gen, pwm_devpath);
      if (ret < 0)
        {
          printf("open %s failed: %d\n", pwm_devpath, -ret);
          return 2;
        }

      ret = wave_gen_start(&gen, (uint32_t)pwm_freq, (uint32_t)pwm_duty);
      if (ret < 0)
        {
          printf("PWM start failed: %d\n", -ret);
          wave_gen_deinit(&gen);
          return 2;
        }

      pwm_on = true;
      printf("PWM test signal: %s, %ld Hz, %ld %%\n",
             pwm_devpath, pwm_freq, pwm_duty);
    }

  ret = wave_core_init(&core, adc_devpath);
  if (ret < 0)
    {
      printf("open %s failed: %d\n", adc_devpath, -ret);
      if (pwm_on)
        {
          wave_gen_deinit(&gen);
        }

      return 2;
    }

  core.swtrig = swtrig;
  printf("ADC ready: %d configured channel(s)\n", core.nchannels);

  /* Try to bring up the OLED; not fatal if it is absent. */
  if (wave_ui_init(&ui) == 0)
    {
      ui_on = true;
      printf("OLED ready: %u x %u\n", ui.xres, ui.yres);
    }

  infinite = (remaining == 0);
  if (window > 0)
    {
      printf("Analysis mode: channel %ld, %ld samples/window\n",
             channel, window);

      while (infinite || remaining > 0)
        {
          ret = wave_core_collect_channel(&core, (uint8_t)channel,
                                          win, (int)window, &rate);
          if (ret < 0)
            {
              printf("collect failed: %d\n", -ret);
              break;
            }

          ret = wave_core_analyze(win, (int)window, rate, &stats);
          if (ret < 0)
            {
              printf("analyze failed: %d\n", -ret);
              break;
            }

          printf("[stats] ch=%ld n=%u rate=%.0f Hz | "
                 "mean=%.3f V rms=%.3f V vpp=%.3f V f=%.1f Hz",
                 channel, stats.nsamples, rate,
                 wave_core_raw_to_volt(stats.mean_raw),
                 wave_core_raw_to_volt(stats.rms_raw),
                 wave_core_raw_to_volt(stats.vpp_raw),
                 stats.freq_zc);

          if (wave_dsp_fft_freq(win, (int)window, rate,
                                s_fft_re, s_fft_im, &ffreq, NULL) == 0)
            {
              printf(" | f_fft=%.1f Hz", ffreq);
            }

          printf("\n");
          fflush(stdout);

          if (ui_on)
            {
              wave_ui_clear(&ui);
              snprintf(line, sizeof(line), "CH=%ld RATE=%.0f HZ",
                       channel, rate);
              wave_ui_text(&ui, 0, 0, line);
              wave_ui_waveform(&ui, win, (int)window, 0, 127, 8, 55);
              snprintf(line, sizeof(line), "RMS=%.2f P=%.2f F=%.0f",
                       wave_core_raw_to_volt(stats.rms_raw),
                       wave_core_raw_to_volt(stats.vpp_raw),
                       stats.freq_zc);
              wave_ui_text(&ui, 0, 56, line);
              wave_ui_flush(&ui);
            }

          if (!infinite && --remaining == 0)
            {
              break;
            }
        }
    }
  else
    {
      /* M2/M3 raw-sample printing mode. */
      while (infinite || remaining > 0)
        {
          n = wave_core_read(&core, samples, WAVE_ADC_BATCH);
          if (n < 0)
            {
              printf("ADC read failed: %d\n", -n);
              break;
            }

          for (i = 0; i < n; i++)
            {
              printf("ch %u: raw %" PRId32 "  %" PRIu32 " mV\n",
                     samples[i].ch, samples[i].raw,
                     wave_core_to_mv(samples[i].raw));

              if (!infinite && --remaining == 0)
                {
                  break;
                }
            }

          fflush(stdout);
        }
    }

  wave_core_deinit(&core);
  if (ui_on)
    {
      wave_ui_deinit(&ui);
    }

  if (pwm_on)
    {
      wave_gen_deinit(&gen);
    }

  printf("OpenWave stopped.\n");
  return 0;
}
OPENWAVE_EOF
```

应用侧同步完。现在做**板级补丁**（补齐 vendor/st 缺失的 OLED 接线）。先创建 `stm32_spi.c`（SPI3 的 CS/DC 控制）：

```bash
cd ~/openvela/vendor/st/boards/stm32h7a3/nucleo-h7a3zi-q/src

cat > stm32_spi.c <<'OPENWAVE_EOF'
/****************************************************************************
 * boards/arm/stm32h7/nucleo-h7a3zi-q/src/stm32_spi.c
 *
 * Board SPI glue for the OpenWave SSD1306 OLED on SPI3:
 *   CS = PE11 (active low), DC = PE12 (command low / data high)
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <debug.h>

#include <sys/param.h>

#include <nuttx/spi/spi.h>
#include <arch/board/board.h>

#include "arm_internal.h"
#include "chip.h"
#include "stm32_gpio.h"
#include "stm32_spi.h"

#include "nucleo-h7a3zi-q.h"

#if defined(CONFIG_SPI)

#ifndef GPIO_SPI3_CS0
#  define GPIO_SPI3_CS0 (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                         GPIO_PORTE | GPIO_PIN11)
#endif

#ifndef GPIO_SSD1306_DC
#  define GPIO_SSD1306_DC (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                           GPIO_PORTE | GPIO_PIN12)
#endif

static const uint32_t g_spi3gpio[] =
{
  GPIO_SPI3_CS0
};

void weak_function stm32_spidev_initialize(void)
{
  stm32_configgpio(GPIO_SPI3_CS0);
  stm32_configgpio(GPIO_SSD1306_DC);
}

void stm32_spi3select(struct spi_dev_s *dev, uint32_t devid, bool selected)
{
  uint32_t index = SPIDEVID_INDEX(devid);

  spiinfo("devid: %d CS: %s\n", (int)devid,
          selected ? "assert" : "de-assert");

  if (index < nitems(g_spi3gpio) && g_spi3gpio[index] != 0)
    {
      stm32_gpiowrite(g_spi3gpio[index], !selected);
    }
}

uint8_t stm32_spi3status(struct spi_dev_s *dev, uint32_t devid)
{
  return 0;
}

#ifdef CONFIG_SPI_CMDDATA
int stm32_spi3cmddata(struct spi_dev_s *dev, uint32_t devid, bool cmd)
{
  /* SSD1306: DC low = command, DC high = data. */
  stm32_gpiowrite(GPIO_SSD1306_DC, !cmd);
  return OK;
}
#endif

#endif /* CONFIG_SPI */
OPENWAVE_EOF
```

再创建 `stm32_ssd1306.c`（OLED 初始化 + `/dev/lcd0` 注册所需的板级接口，RES=PE13）：

```bash
cat > stm32_ssd1306.c <<'OPENWAVE_EOF'
/****************************************************************************
 * boards/arm/stm32h7/nucleo-h7a3zi-q/src/stm32_ssd1306.c
 *
 * OpenWave SSD1306 OLED (128x64, SPI) board glue:
 *   SPI3: SCK=PB3, MOSI=PB5; CS=PE11, DC=PE12, RES=PE13
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <debug.h>
#include <unistd.h>

#include <nuttx/board.h>
#include <nuttx/lcd/lcd.h>
#include <nuttx/lcd/ssd1306.h>
#include <nuttx/spi/spi.h>

#include "stm32_gpio.h"
#include "stm32_spi.h"
#include "nucleo-h7a3zi-q.h"

#ifdef CONFIG_LCD_SSD1306_SPI

#ifndef GPIO_SPI3_CS0
#  define GPIO_SPI3_CS0 (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                         GPIO_PORTE | GPIO_PIN11)
#endif

#ifndef GPIO_SSD1306_DC
#  define GPIO_SSD1306_DC (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                           GPIO_PORTE | GPIO_PIN12)
#endif

#ifndef GPIO_SSD1306_RST
#  define GPIO_SSD1306_RST (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                            GPIO_PORTE | GPIO_PIN13)
#endif

static struct lcd_dev_s *g_lcddev;

int board_ssd1306_initialize(int busno)
{
  struct spi_dev_s *spi;
  const int devno = 0;

  /* Configure the OLED control pins and pulse the hardware reset. */
  stm32_configgpio(GPIO_SPI3_CS0);
  stm32_configgpio(GPIO_SSD1306_DC);
  stm32_configgpio(GPIO_SSD1306_RST);
  stm32_gpiowrite(GPIO_SSD1306_RST, false);
  usleep(10000);
  stm32_gpiowrite(GPIO_SSD1306_RST, true);
  usleep(10000);

  spi = stm32_spibus_initialize(busno);
  if (spi == NULL)
    {
      lcderr("ERROR: Failed to initialize SPI port %d\n", busno);
      return -ENODEV;
    }

  g_lcddev = ssd1306_initialize(spi, NULL, devno);
  if (g_lcddev == NULL)
    {
      lcderr("ERROR: Failed to bind SPI port %d to OLED %d\n", busno, devno);
      return -ENODEV;
    }

  lcdinfo("Bound SPI port %d to OLED %d\n", busno, devno);
  g_lcddev->setpower(g_lcddev, CONFIG_LCD_MAXPOWER);
  ssd1306_fill(g_lcddev, 0x00); /* start blank */
  return OK;
}

struct lcd_dev_s *board_ssd1306_getdev(void)
{
  return g_lcddev;
}

int board_lcd_initialize(void)
{
  int ret;

  ret = board_ssd1306_initialize(3); /* SPI3 */
  if (ret < 0)
    {
      lcderr("ERROR: Failed to initialize SSD1306\n");
      return ret;
    }

  return OK;
}

struct lcd_dev_s *board_lcd_getdev(int devno)
{
  return board_ssd1306_getdev();
}

void board_lcd_uninitialize(void)
{
}

#endif /* CONFIG_LCD_SSD1306_SPI */
OPENWAVE_EOF
```

把 LCD 初始化挂进 bringup（自动在最后一个 `return OK;` 前插入），并把 `stm32_spi.c` 加进板级 Makefile：

```bash
python3 <<'PYEOF'
p = '/home/user/openvela/vendor/st/boards/stm32h7a3/nucleo-h7a3zi-q/src/stm32_bringup.c'
s = open(p, encoding='utf-8').read()

if '#include <nuttx/lcd/lcd_dev.h>' not in s:
    s = s.replace('#include <nuttx/config.h>',
                  '#include <nuttx/config.h>\n#include <nuttx/lcd/lcd_dev.h>', 1)

block = '''#ifdef CONFIG_LCD_DRIVER
  /* Initialize the SSD1306 OLED and register /dev/lcd0 */
  ret = board_lcd_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: board_lcd_initialize failed: %d\\n", ret);
    }
  else
    {
      ret = lcddev_register(0);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: lcddev_register failed: %d\\n", ret);
        }
    }
#endif /* CONFIG_LCD_DRIVER */

'''

marker = '  return OK;'
idx = s.rfind(marker)
if idx < 0:
    raise SystemExit('marker not found')
s = s[:idx] + block + s[idx:]
open(p, 'w', encoding='utf-8').write(s)
print('bringup patched OK')
PYEOF

sed -i '/ifeq ($(CONFIG_LCD_SSD1306),y)/i ifeq ($(CONFIG_SPI),y)\nCSRCS += stm32_spi.c\nendif\n' ~/openvela/vendor/st/boards/stm32h7a3/nucleo-h7a3zi-q/src/Makefile
```

最后在 menuconfig 里开 LCD 相关配置（按 `/` 搜索依次打开）：

```bash
cd ~/openvela
./build.sh vendor/st/boards/stm32h7a3/nucleo-h7a3zi-q/configs/m2-bsp menuconfig
```

- 搜 `LCD Driver Support` → 打开（`CONFIG_LCD=y`）
- 在其下打开 **`UG-2864HSWEG01 OLED Display Module (SSD1306)`**（128×64，会自动连带 SSD1306 驱动）
- 在其下打开 **`LCD character driver`**（`CONFIG_LCD_DRIVER=y`，生成 `/dev/lcd0`）
- 搜 `CMDDATA` → 打开 **SPI CMDDATA support**（`CONFIG_SPI_CMDDATA=y`，DC 线控制需要）
- 搜 `LIBC_FLOATINGPOINT` → 打开（串口/屏幕打印小数需要）
- 确认 `CONFIG_STM32H7_SPI3=y` 是开的（本来就是）

保存（`Q`→`Y`）后编译：

```bash
./build.sh $(pwd)/vendor/st/boards/stm32h7a3/nucleo-h7a3zi-q/configs/m2-bsp -j$(nproc)
```

